#include <stdio.h>

int main(void) {
    int e, d;
    if (scanf("%d %d", &e, &d) == 2) {
        if (e > d) {
            printf("%d\n", e + d);
        } else {
            printf("%d\n", 2 * (d - e));
        }
    }
    return 0;
}
```

